from collections import Counter

class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        n = len(words)
        masks = [sum(1 << (ord(c) - 97) for c in w) for w in words]
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for i in range(n):
            for j in range(i + 1, n):
                d = masks[i] ^ masks[j]
                pc = bin(d).count('1')
                if pc == 0 or pc == 1 or (pc == 2 and masks[i].bit_count() == masks[j].bit_count()):
                    ri, rj = find(i), find(j)
                    if ri != rj:
                        parent[ri] = rj
        cnt = Counter(find(i) for i in range(n))
        return [len(cnt), max(cnt.values())]

