    vector<int> groupStrings(vector<string>& words) {
        int n = words.size();
        vector<int> masks(n, 0);
        for (int i = 0; i < n; ++i)
            for (char ch : words[i]) masks[i] |= 1 << (ch - 'a');
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        function<int(int)> find = [&](int x) {
            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
            return x;
        };
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j) {
                int d = masks[i] ^ masks[j];
                bool conn = d == 0 || __builtin_popcount(d) == 1 ||
                            (__builtin_popcount(d) == 2 &&
                             __builtin_popcount(masks[i]) == __builtin_popcount(masks[j]));
                if (conn) {
                    int ri = find(i), rj = find(j);
                    if (ri != rj) parent[ri] = rj;
                }
            }
        unordered_map<int, int> cnt;
        int largest = 0;
        for (int i = 0; i < n; ++i) largest = max(largest, ++cnt[find(i)]);
        return {(int)cnt.size(), largest};
    }
