from collections import Counter

class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        n = len(words)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def unite(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
        seen = {}
        for i, w in enumerate(words):
            m = 0
            for ch in w:
                m |= 1 << (ord(ch) - 97)
            if m in seen:
                unite(i, seen[m])
            else:
                seen[m] = i
            for b in range(26):
                nb = m ^ (1 << b)
                if nb in seen:
                    unite(i, seen[nb])
            for b in range(26):
                if m >> b & 1:
                    base = m ^ (1 << b)
                    for c in range(26):
                        cand = base | (1 << c)
                        if not base >> c & 1 and cand in seen:
                            unite(i, seen[cand])
        cnt = Counter(find(i) for i in range(n))
        return [len(cnt), max(cnt.values())]

