public:
    vector<int> groupStrings(vector<string>& words) {
        int n = words.size();
        parent.resize(n);
        iota(parent.begin(), parent.end(), 0);
        unordered_map<int, int> seen;
        for (int i = 0; i < n; ++i) {
            int m = 0;
            for (char ch : words[i]) m |= 1 << (ch - 'a');
            if (seen.count(m)) unite(i, seen[m]);
            else seen[m] = i;
            for (int b = 0; b < 26; ++b) {
                auto it = seen.find(m ^ (1 << b));
                if (it != seen.end()) unite(i, it->second);
            }
            for (int b = 0; b < 26; ++b) {
                if (m >> b & 1) {
                    int base = m ^ (1 << b);
                    for (int c = 0; c < 26; ++c) {
                        if (!(base >> c & 1)) {
                            auto it = seen.find(base | (1 << c));
                            if (it != seen.end()) unite(i, it->second);
                        }
                    }
                }
            }
        }
        unordered_map<int, int> cnt;
        int largest = 0;
        for (int i = 0; i < n; ++i) largest = max(largest, ++cnt[find(i)]);
        return {(int)cnt.size(), largest};
    }
};

