class Solution {
    int[] parent;
    int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a != b) parent[a] = b;
    }
    public int[] groupStrings(String[] words) {
        int n = words.length;
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int m = 0;
            for (char ch : words[i].toCharArray()) m |= 1 << (ch - 'a');
            if (seen.containsKey(m)) unite(i, seen.get(m));
            else seen.put(m, i);
            for (int b = 0; b < 26; b++) {
                int nb = m ^ (1 << b);
                if (seen.containsKey(nb)) unite(i, seen.get(nb));
            }
            for (int b = 0; b < 26; b++) {
                if ((m >> b & 1) == 1) {
                    int base = m ^ (1 << b);
                    for (int c = 0; c < 26; c++)
                        if ((base >> c & 1) == 0 && seen.containsKey(base | (1 << c)))
                            unite(i, seen.get(base | (1 << c)));
                }
            }
        }
        Map<Integer, Integer> cnt = new HashMap<>();
        int largest = 0;
        for (int i = 0; i < n; i++)
            largest = Math.max(largest, cnt.merge(find(i), 1, Integer::sum));
        return new int[]{cnt.size(), largest};
    }
};

